<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'
import { Search, SlidersHorizontal, Building2, MapPin, TrendingUp, X } from 'lucide-vue-next'
import { companiesApi } from '../api/client'
import SectionTitle from '../components/SectionTitle.vue'
import UiState from '../components/UiState.vue'
import PaginationBar from '../components/PaginationBar.vue'
import BaseModal from '../components/BaseModal.vue'
const rows=ref<any[]>([]), selected=ref<any>(null), loading=ref(false), error=ref(''), total=ref(0), page=ref(1), pageSize=10, search=ref(''), region=ref(''), industry=ref(''), revenueMin=ref(''), revenueMax=ref(''), growthMin=ref('')
let debounce: ReturnType<typeof setTimeout>
async function load(){loading.value=true;error.value='';try{const r=await companiesApi.list({search:search.value||undefined,region:region.value||undefined,industry:industry.value||undefined,revenue_min:revenueMin.value||undefined,revenue_max:revenueMax.value||undefined,growth_min:growthMin.value||undefined,page:page.value,page_size:pageSize});rows.value=r.items;total.value=r.total}catch(e:any){error.value=e.userMessage||'Не удалось получить компании'}finally{loading.value=false}}
function delayed(){clearTimeout(debounce);page.value=1;debounce=setTimeout(load,300)}
function clear(){search.value=region.value=industry.value=revenueMin.value=revenueMax.value=growthMin.value='';page.value=1;load()}
watch(page,load);onMounted(load)
const money=(n:any)=>n==null?'—':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',notation:'compact',maximumFractionDigits:1}).format(n)
</script>
<template><main class="page"><SectionTitle title="Радар присутствия" subtitle="Поиск компаний, оценка потенциала и анализ динамики бизнеса."/><section class="panel filter-panel"><div class="filter-heading"><div><SlidersHorizontal :size="17"/><strong>Фильтры компаний</strong></div><button class="text-button" @click="clear"><X :size="14"/> Сбросить</button></div><div class="filters-grid"><label class="field search-field"><span>Поиск</span><div class="input-icon"><Search/><input v-model="search" placeholder="Название, ИНН или ключевое слово" @input="delayed"/></div></label><label class="field"><span>Регион</span><input v-model="region" placeholder="Например, Москва" @input="delayed"/></label><label class="field"><span>Отрасль</span><input v-model="industry" placeholder="Отрасль" @input="delayed"/></label><label class="field"><span>Выручка от, ₽</span><input v-model="revenueMin" type="number" min="0" placeholder="0" @change="delayed"/></label><label class="field"><span>Выручка до, ₽</span><input v-model="revenueMax" type="number" min="0" placeholder="Без ограничений" @change="delayed"/></label><label class="field"><span>Рост от, %</span><input v-model="growthMin" type="number" placeholder="0" @change="delayed"/></label></div></section><section class="panel list-panel"><div class="panel-heading"><div><h2>Компании</h2><p>Найдено: {{total.toLocaleString('ru-RU')}}</p></div><span class="subtle-label">Реестр организаций</span></div><UiState :loading="loading" :error="error" :empty="!rows.length" empty-text="По заданным параметрам компании не найдены." @retry="load"><div class="company-grid"><button v-for="c in rows" :key="c.id" class="company-card" @click="selected=c"><div class="company-logo">{{String(c.name||'?').split(' ').map((x:string)=>x[0]).slice(0,2).join('').toUpperCase()}}</div><div class="company-main"><strong>{{c.name}}</strong><small><MapPin :size="13"/>{{c.region||'Регион не указан'}} · {{c.industry||'Отрасль не указана'}}</small></div><div class="company-metrics"><span>Выручка</span><strong>{{money(c.revenue)}}</strong></div><div class="growth" :class="Number(c.growth)>=0?'positive':'negative'"><TrendingUp :size="15"/>{{c.growth==null?'—':`${c.growth>0?'+':''}${c.growth}%`}}</div></button></div></UiState><PaginationBar v-if="!loading&&!error&&total>pageSize" :page="page" :page-size="pageSize" :total="total" @change="page=$event"/></section><BaseModal v-if="selected" title="Карточка компании" @close="selected=null"><div class="detail-hero"><div class="company-logo large"><Building2/></div><div><h3>{{selected.name}}</h3><p>{{selected.industry||'Отрасль не указана'}}</p></div></div><div class="detail-grid"><div><small>Регион</small><strong>{{selected.region||'—'}}</strong></div><div><small>Выручка</small><strong>{{money(selected.revenue)}}</strong></div><div><small>Рост</small><strong>{{selected.growth==null?'—':`${selected.growth}%`}}</strong></div><div><small>ИНН</small><strong>{{selected.inn||'—'}}</strong></div></div><p class="detail-description">{{selected.description||'Дополнительная информация отсутствует.'}}</p><template #footer><button class="btn btn-secondary" @click="selected=null">Закрыть</button></template></BaseModal></main></template>